const matrix = JSON.parse(contents["compatibility-matrix.json"]);
const sources = JSON.parse(contents["source-identities.json"]);
const result = JSON.parse(contents["result.json"]);
const issue = JSON.parse(contents["issue-object.json"]);
const defects = JSON.parse(contents["defects.json"]);
const assert = (value, message) => { if (!value) throw Error(message); };
for (const [name, content] of Object.entries(contents)) {
  if (name.endsWith(".json")) assert(content === JSON.stringify(JSON.parse(content), null, 2) + "\n", "JSON formatting: " + name);
  assert(content.endsWith("\n") && !content.includes("\r") && !content.includes("\0"), "Text encoding: " + name);
  assert(!content.split("\n").some(line => /[ \t]+$/.test(line)), "Whitespace: " + name);
}
assert(JSON.stringify(issue.issue) === JSON.stringify(authoritativeIssue), "Issue mismatch");
const sourceIds = new Set(sources.sources.map(source => source.id));
assert(new Set(matrix.scenarios.map(row => row.id)).size === matrix.scenarios.length, "Duplicate scenarios");
for (const row of matrix.scenarios) {
  assert([1, 2, 3].includes(row.acceptanceCriterion), "Bad criterion");
  for (const id of row.sourceIds) assert(sourceIds.has(id), "Source missing");
  for (const variant of row.variants) assert(variant in matrix.variantDefinitions, "Variant missing");
  assert(JSON.stringify(Object.keys(row.results)) === JSON.stringify(matrix.platforms), "Platform missing");
  for (const platform of matrix.platforms) {
    const value = row.results[platform];
    assert(value.state === "OPEN" && value.evidence.length === 0 && value.defects.length === 0, "False native evidence");
  }
}
for (const criterion of [1, 2, 3]) assert(matrix.scenarios.some(row => row.acceptanceCriterion === criterion), "Criterion missing");
assert(matrix.releaseCandidate.state === "UNDECLARED" && matrix.releaseCandidate.id === null, "Invented RC");
assert(matrix.nativeAcceptance === "OPEN" && result.nativeAcceptance === "OPEN", "Native gate lost");
assert(result.counts.platformCells === matrix.scenarios.length * matrix.platforms.length, "Cell count mismatch");
assert(result.counts.nativeOpen === result.counts.platformCells && result.counts.nativePass === 0, "False closure");
assert(defects.runtimeDefects.length === 0 && defects.candidates[0].state === "SOURCE_RISK_NOT_RUNTIME_REPRODUCED", "Wrong defect classification");
for (const source of sources.sources) assert(/^[a-f0-9]{64}$/.test(source.sha256), "Invalid hash");
const names = new Set([...Object.keys(contents), "checks.json"]);
for (const match of contents["README.md"].matchAll(/\]\(([^)]+)\)/g)) assert(names.has(match[1]), "Missing link");
for (const path of result.evidencePaths) assert(names.has(path), "Missing evidence");
